// ============================================================
// AGENTFORGE JEWELLERY AGENT — Normalize + Master prompt builder
// Handles BOTH single and bulk modes.
// Input  : webhook body from app/api/jewellery/generate/route.ts
// Output : N items (1 per image), each with master_prompt + source URL
// ============================================================

const body = $json.body || $json;
const s = body.shared_settings || {};
const mode = body.generation_mode || 'single';
const batchId = body.batch_id || null;

const rawItems = Array.isArray(body.items) && body.items.length
  ? body.items
  : [{
      generation_id: body.generation_id,
      source_image_url: body.source_image_url || s.source_image_url,
      original_name: 'image-1'
    }];

if (!rawItems.length) throw new Error('No items to process — payload has no images.');

// ---------- Aspect / quality ----------
const sizeStr = String(s.output_size || 'Square 1080x1080');
const isMobile = /Mobile|1920|9:16/i.test(sizeStr);
const aspect = isMobile ? '9:16 vertical (1080x1920)' : '1:1 square (1080x1080)';
const quality = String(s.output_quality || 'Premium');

// ---------- Branding reserve ----------
const cd = s.company_details || {};
const hasBrandingText = Boolean(cd.company_name) || Boolean(cd.website) || Boolean(cd.phone) || Boolean(cd.address);
const reserveBottomStrip = hasBrandingText;
const reserveTopRight = true;

// ---------- Style guides ----------
const SHOOT_STYLE_GUIDE = {
  'Luxury Studio': 'premium softbox studio lighting, dark velvet or gradient grey background, museum-quality jewellery showcase, dramatic key light on stones',
  'White Catalogue': 'pure white seamless background, even shadowless ecommerce lighting, Amazon/Flipkart catalogue ready, ultra clean',
  'Bridal Editorial': 'rich warm gold tones, ornate silk drape backdrop, candlelight + softbox mix, Vogue Bridal magazine feel',
  'Macro Detail': 'extreme macro shot, ring-light reflections in every stone facet, shallow depth of field, gemstone-first composition',
  'Lifestyle Campaign': 'natural daylight cafe / outdoor terrace mood, modern Indian woman lifestyle, soft bokeh, social-media ad feel',
  'Indian Model': 'warm honey-tan Indian skin tone, natural Indian facial features, traditional or fusion styling, soft glow makeup',
  'Bridal Look': 'heavy bridal styling with subtle mehndi, traditional bridal makeup, dupatta drape, regal posture, wedding photography feel',
  'Luxury Editorial': 'high-fashion editorial aesthetic, dramatic shadow play, designer-magazine feel, model styled as luxury brand muse',
  'Minimal Modern': 'minimal scandi-influenced styling, soft neutral palette, modern Indian woman, clean understated elegance'
};
const MODEL_TYPE_GUIDE = {
  'No Model': 'product-only — no human, no hand. Pure jewellery composition on the chosen surface/prop.',
  'Hand Model': 'elegant feminine hand with manicured natural nails. Hand placement keeps the jewellery as the visual hero.',
  'Couple Hands': 'two hands together (engagement / wedding feel) — one masculine, one feminine. Subtle warmth.',
  'Female Model': 'Indian female adult model, jewellery clearly visible, styled around the piece.',
  'Bridal Model': 'Indian bride in full bridal styling — dupatta, traditional outfit, bridal makeup, regal pose.',
  'Luxury Flat Lay': 'top-down flat lay on a premium surface (velvet / silk / marble). Jewellery is the hero with curated props.',
  'Macro Detail': 'extreme zoom on the jewellery only — no model, no full piece view. Focus on a single stone / facet / engraving.',
  'Ear Close-up': 'extreme close-up of one ear wearing the earring, side profile, focus on earring sparkle.',
  'Bust Portrait': 'shoulders-up portrait with face and jewellery both visible, elegant pose.',
  'Half Body': 'waist-up lifestyle shot showing model styling around the jewellery.',
  'Full Body': 'editorial full-body shot with the jewellery as the focal accessory.',
  'Neck Focus': 'tight crop on neckline showing the necklace draped naturally.',
  'Neck Close-up': 'extreme close-up of neckline — jewellery detail and skin texture only.',
  'Wrist Close-up': 'tight wrist crop with bracelet/kada as hero.',
  'Lifestyle Hand': 'natural hand pose in lifestyle context (holding coffee cup, on lap, etc.).',
  'Detail Close-up': 'extreme detail crop of the jewellery — pattern, stone setting, engraving.',
  'Editorial Scene': 'staged scene with model + jewellery in an editorial context (palace, garden, studio set).'
};
const ACCESSORY_GUIDE = {
  'No Accessories': 'no props — clean focus on the jewellery only.',
  'Flat Lay': 'top-down flat lay arrangement on a premium fabric or surface.',
  'Velvet Box': 'jewellery resting on or beside an open black/maroon velvet box — luxury showroom feel.',
  'Marble Surface': 'placed on polished white-and-grey veined marble with subtle reflection.',
  'Silk Drape': 'cascading silk fabric (cream, ivory or jewel-tone) as backdrop / under-layer.',
  'Rose Petals': 'scattered fresh rose petals as romantic accent — sparse, tasteful.',
  'Marigold + Diya': 'marigold flowers and a small lit diya — temple/festival jewellery context.',
  'Diamond Sparkle Set': 'loose crystals and mirror shards catching light — adds sparkle drama.',
  'Pearl String Decor': 'strands of pearls draped softly around the jewellery as accent.',
  'Wooden Antique Tray': 'placed on a vintage carved wooden tray — heritage / antique jewellery context.'
};
const CAMERA_ANGLE_GUIDE = {
  'Auto Angle': 'choose the most flattering angle for this jewellery type',
  'Eye Level': 'straight-on eye-level shot, parallel to subject',
  '45° Angle': '45-degree tilt — classic jewellery showcase angle',
  'Top Down': 'directly overhead flat-lay perspective',
  'Side Profile': 'pure side view — best for earrings and pendants'
};
const FACE_GUIDE = {
  'Soft Smile': 'gentle warm smile, eyes relaxed',
  'Confident': 'confident closed-mouth expression, direct gaze',
  'Serious': 'serious editorial expression, eyes off-camera',
  'Royal': 'regal bridal expression, chin slightly raised',
  'Natural': 'candid natural expression, no posing'
};
const pickGuide = (tbl, k, fb) => tbl[k] || `"${k}"${fb ? ' — ' + fb : ''}`;

const shootStyleDesc = pickGuide(SHOOT_STYLE_GUIDE, s.shoot_style, 'premium photography style');
const modelTypeDesc = pickGuide(MODEL_TYPE_GUIDE, s.model_type, 'as described');
const accessoryDesc = pickGuide(ACCESSORY_GUIDE, s.accessories, 'as described');
const cameraAngleDesc = pickGuide(CAMERA_ANGLE_GUIDE, s.camera_angle, 'as described');
const faceDesc = pickGuide(FACE_GUIDE, s.face_expression, 'natural expression');

const moreList = Array.isArray(s.more_jewellery) && s.more_jewellery.length
  ? ` (${s.more_jewellery.join(', ')})`
  : '';
const jewelLabel = `${s.jewellery_type || 'Jewellery piece'}${moreList}`;

function buildPrompt(idx) {
  return `
ROLE: You are a senior luxury jewellery photographer + AI image editor working for an Indian D2C jewellery brand.
OBJECTIVE: Take the reference jewellery photo I am providing and produce a single ${aspect} ${quality}-grade catalogue/editorial visual that strictly preserves the original jewellery while restyling the scene per the spec below.${mode === 'bulk' ? `\n[Batch ${idx + 1} of ${rawItems.length} — keep style consistent across the batch.]` : ''}

========================================================
  HARD RULES — NEVER VIOLATE
========================================================
1. PRESERVE THE JEWELLERY EXACTLY as in the reference image:
   - same overall SHAPE, contour and silhouette
   - same NUMBER of stones, same stone CUT, same stone COLOR
   - same METAL TONE (yellow gold / rose gold / silver / white gold / oxidized / kundan / polki)
   - same engravings, embossed patterns, polish texture, finishing
   - DO NOT redesign, restyle, recolor or "improve" the piece. Style the scene AROUND it.
2. NO TEXT, NO SKU, NO PRODUCT CODE, NO BARCODE, NO NUMBERS, NO PRICE, NO LABELS anywhere on or near the jewellery. The image must be 100% free of typography and codes.
3. NO LOGOS of any kind baked into the image — "AgentForge", "AF", brand watermarks, etc. are added separately client-side after this image is generated. Your output should be a clean photograph only.
4. ${reserveBottomStrip ? 'RESERVE the BOTTOM 14% of the canvas as a clean, gently blurred, neutral surface. No jewellery, no model face, no busy props in that strip. A branding text strip will be overlaid post-process.' : 'Compose freely across the full canvas.'}
5. ${reserveTopRight ? 'Keep the TOP-RIGHT corner (roughly 18% width x 18% height) visually calm — avoid bright highlights, faces or critical jewellery detail there. A small logo badge will be overlaid post-process.' : ''}
6. Output must be a SINGLE photograph — no collages, no split frames, no before/after panels.

========================================================
  SHOOT SPEC
========================================================
- Jewellery: ${jewelLabel}
- Shoot Style & Model Look: "${s.shoot_style}" → ${shootStyleDesc}
- Accessories / Props: "${s.accessories}" → ${accessoryDesc}
- Model Type: "${s.model_type}" → ${modelTypeDesc}
- Pose: "${s.pose}"
- Face Expression: "${s.face_expression}" → ${faceDesc}
- Camera Angle: "${s.camera_angle}" → ${cameraAngleDesc}
- Output Frame: ${aspect}
- Quality Tier: ${quality}${quality === 'Ultra HD' ? ' — push micro-detail, extra sharpness, crisper stone facets, finer skin texture' : ''}

========================================================
  CLIENT NOTES (must be respected verbatim)
========================================================
- Jewellery protection notes: ${s.jewellery_notes ? `"${s.jewellery_notes}"` : '(none provided — default to faithful preservation)'}
- Model styling notes: ${s.model_notes ? `"${s.model_notes}"` : '(none)'}
- Custom instruction: ${s.custom_instruction ? `"${s.custom_instruction}"` : '(none)'}

========================================================
  TECHNICAL
========================================================
- DSLR-grade detail, accurate metallic reflections, true-to-life gemstone color
- Studio softbox + rim light unless the chosen style says otherwise
- Skin tone for Indian models: warm honey-tan, natural Indian facial features, soft minimal makeup unless Bridal style is selected
- Color grading: jewellery-first — background must support, never compete
- Aspect: ${aspect}
- Final: clean, share-ready, no text, no logos baked in, no SKU

Return ONE image only.
`.trim();
}

const out = rawItems.map((item, idx) => {
  if (!item.source_image_url) throw new Error(`Item ${idx} missing source_image_url`);
  return {
    json: {
      mode,
      batch_id: batchId,
      batch_size: rawItems.length,
      batch_index: idx,
      generation_id: item.generation_id,
      user_id: body.user_id,
      source_image_url: item.source_image_url,
      original_name: item.original_name || `image-${idx + 1}`,
      aspect_ratio: isMobile ? '9:16' : '1:1',
      is_free_account: Boolean(s.af_watermark),
      company_details: cd,
      master_prompt: buildPrompt(idx)
    }
  };
});
return out;

// Read FAL sync response → pull the first image URL.
// FAL sync returns: { images: [{ url, content_type, width, height }], description, seed, ... }
const resp = $json;
const meta = $('Normalize + Build Per-Item Prompts').item.json;

// HTTP node error path (continueOnFail) may give us { error: ... }
if (resp?.error || resp?.detail) {
  return [{
    json: {
      ...meta,
      ok: false,
      error_message: 'FAL error: ' + JSON.stringify(resp.error || resp.detail).slice(0, 400)
    }
  }];
}

const images = resp?.images || resp?.data?.images || [];
const first = images[0];
if (!first?.url) {
  return [{
    json: {
      ...meta,
      ok: false,
      error_message: 'FAL returned no image. Raw: ' + JSON.stringify(resp).slice(0, 400)
    }
  }];
}

const mime = first.content_type || 'image/png';
const ext = mime.includes('jpeg') ? 'jpg' : 'png';
const objectPath = `jewellery-outputs/${meta.user_id || 'guest'}/${Date.now()}-${meta.generation_id}.${ext}`;

return [{
  json: {
    ...meta,
    ok: true,
    fal_image_url: first.url,
    output_mime: mime,
    output_ext: ext,
    object_path: objectPath,
    fal_seed: resp.seed || null
  }
}];

// Build the public URL for the freshly uploaded Supabase object.
const meta = $('Extract FAL Result').item.json;
const supabaseUrl = $env.SUPABASE_URL;
const publicUrl = `${supabaseUrl}/storage/v1/object/public/designs/${meta.object_path}`;
return [{ json: { ...meta, output_url: publicUrl } }];

// Collect this loop iteration's result into workflow static data.
const meta = $json;
const state = $getWorkflowStaticData('node');
state.results = state.results || [];
state.results.push({
  generation_id: meta.generation_id,
  status: meta.ok === false ? 'failed' : 'completed',
  output_url: meta.output_url || null,
  error_message: meta.error_message || null,
  original_name: meta.original_name
});
return [{ json: meta }];

// Runs after Split In Batches finishes all iterations.
// Reads per-item results from workflow static data and emits a single item
// containing the final response object — 'Respond to Webhook' then serialises
// it via {{ $json }}.
const state = $getWorkflowStaticData('node');
const results = Array.isArray(state.results) ? state.results : [];
state.results = []; // reset for next webhook run

const first = $('Normalize + Build Per-Item Prompts').first().json || {};
const completed = results.filter(r => r.status === 'completed');
const failed = results.filter(r => r.status === 'failed');

return [{
  json: {
    success: failed.length === 0,
    mode: first.mode || 'single',
    batch_id: first.batch_id || null,
    total: results.length,
    completed: completed.length,
    failed: failed.length,
    // single-mode convenience fields
    generation_id: results[0]?.generation_id || null,
    image_url: results[0]?.output_url || null,
    output_url: results[0]?.output_url || null,
    // full per-item map (bulk mode)
    results
  }
}];
